"""OR-04: individually authored corridor/rhythm lesson with retained strength.

The prior session records provide exact familiar strength mechanics and doses;
all OR-04 purposes, selection, sequencing, clocks and continuity are authored here.
The exported document expands every exercise rather than telling a coach to repeat
another session. No future workout is selected or generated by this file.
"""
import copy
import json
from session_tools import AGES, MODES, ROOT, dose, save

def exercise(key,name,component,mapping,purpose,execution,cues,errors,rationale,metadata,make,competency,progression,continuity):
    return dict(key=key,name=name,component=component,mapping=mapping,set_purpose=purpose,
        execution=execution,cues=cues,errors=errors,rationale=rationale,metadata=metadata,
        age_prescriptions={a:{m:make(a,m) for m in MODES} for a in AGES},competency=competency,
        progression=progression,continuity=continuity)

def standing(sets=1):
    d=dose('Quiet Bilateral Standing — no-step orientation teaching task',sets,reps=1,tempo_s=10 if sets else 0,
        effort='Bodyweight, minimal effort.2s settle,2s comfortable quiet standing,6s reset. Arms relaxed, knees unlocked; no deliberate lowering, travel or technical knee target.',rest_s=60,
        notes='This observes simple orientation/stop-cue participation only. No travel, marching or upright-running pass follows.')
    if not sets:d.update(variant='Omitted or unavailable opportunity — no physical work',repetitions_per_set=0,
        effort_load='No physical effort assigned; observation/recovery only.',notes='Zero physical work: compressed L omits E1, and D-only running routes are unavailable in L.')
    d.update(active_s=10 if sets else 0,return_s=0,walk_outbound_m=0,run_target_m=0,runoff_m=0,
        march_steps_per_side=0,execution_segments=[{'name':'settle','seconds':2},{'name':'quiet_hold','seconds':2},{'name':'reset','seconds':6}] if sets else [])
    return d

def march(sets=1):
    d=dose('Basic alternating march in place — explicit stationary teaching adaptation',sets,reps=4 if sets else 0,per_side=2 if sets else 0,tempo_s=2,
        effort='Bodyweight, easy2/10. Two seconds per comfortable walking-height step; four alternating steps, two each side, then settle2s. Use relaxed opposite arm/leg timing without a forced thigh-height target.',rest_s=60,handling_s=2 if sets else 0,
        notes='One foot remains supported; no flight or forward travel. Each left/right step is one count, not a two-step cycle. This is the same basic pattern used in the instructional preparation; it is not exact traveling A-March or sprint exposure.' if sets else 'Compressed L omits this additional rhythm set; zero work.')
    d.update(active_s=10 if sets else 0,return_s=0,walk_outbound_m=0,run_target_m=0,runoff_m=0,march_steps_per_side=2 if sets else 0,
        execution_segments=[{'name':'four_alternating_steps','seconds':8},{'name':'settle','seconds':2}] if sets else [])
    if not sets:d.update(effort_load='No physical effort assigned; this follow-up is omitted.',variant='Omitted stationary follow-up — compressed L')
    return d

def main_sets(mode):
    if mode.endswith('_L'):return 0 if mode.startswith('compressed') else 1
    return 1 if mode.startswith('compressed') else 2

def travel(age,mode,key,route):
    count=main_sets(mode) if key=='E1' else 1
    if route=='stationary_march':return march(count) if key in ['P2','E1'] else standing(count)
    if route=='stationary_stand':return standing(count)
    if not count:
        d=standing(0);d['variant']='Omitted follow-up — compressed L ends locomotor work after the counted corridor walk';return d
    long=route.startswith('long')
    run=route in ['long_run','short_acc'] and key!='E0'
    if key=='P2':
        active=15 if run else 18;ret=20;walk_m=0 if run else 15;target=5 if run else 0;runoff=10 if run else 0
        variant='Standing Static Short Start — low-intent teaching adaptation' if run else 'Short Corridor Walk — ordinary walking orientation'
        phases=[('five_metre_easy_start',3),('ten_metre_gradual_runout',9),('exit',3)] if run else [('fifteen_metre_walk',15),('exit',3)]
    elif key=='E0' or not run:
        active=45 if long else 20;ret=40 if long else 20;walk_m=35 if long else 15;target=0;runoff=0
        variant='Full Corridor Walk — build/finish/runoff/return orientation' if long else 'Short Corridor Walk — acceleration/runout/return orientation'
        phases=[('ordinary_outbound_walk',35 if long else 15),('marker_orientation_and_exit',10 if long else 5)]
    else:
        active=25 if long else 15;ret=40 if long else 20;walk_m=0;target=20 if long else 5;runoff=15 if long else 10
        variant='Easy Build and Upright Rhythm Run — explicitly authored teaching adaptation' if long else 'Standing Static Short Start — low-intent teaching adaptation'
        phases=[('ten_metre_smooth_build',5),('ten_metre_easy_upright_rhythm',5),('fifteen_metre_gradual_runoff',12),('exit',3)] if long else [('five_metre_easy_start',3),('ten_metre_gradual_runout',9),('exit',3)]
    d=dose(variant,count,reps=1,tempo_s=active,
        effort='Bodyweight; smooth easy intent rising from about2/10 toward3/10, then retain a relaxed comfortable rhythm. No maximal effort, measured speed quota or fly-zone result.' if run else
        'Bodyweight, ordinary conversational walking about2/10. Recognize the assigned markers and exit; no jog, forced technical thigh height, abrupt terminal plant or timed redirect.',rest_s=90 if key in ['E0','E1'] else 60,
        notes=f'Each set is one whole counted attempt including any fault. Active/exit estimate{active}s; separate outside walking return{ret}s. These are logistics estimates, not forced cadence. No corrective or assessment repetition is added. Exact steps/contacts and return metres remain actual observations.')
    d.update(active_s=active,return_s=ret,walk_outbound_m=walk_m,run_target_m=target,runoff_m=runoff,march_steps_per_side=0,
        running_intent='easy_teaching' if run else 'none',execution_segments=[{'name':n,'seconds':v} for n,v in phases])
    return d

exercises=[
exercise('P1','Find a comfortable upright rhythm','Prepare & Access','BASIC-MARCH-TEACH; quiet-standing alternative is separately mapped',
 'One short set makes an upright trunk and relaxed opposite arm/leg rhythm visible before the running lesson. It deliberately repeats the useful basic preparation pattern with one focused observation; it does not add skipping or a technical height challenge.',
 'Stay in the assigned personal bay. Alternate four comfortable marching steps in place, two each side, at2s per step; settle2s. Keep one foot supported throughout and use relaxed opposite arm/leg motion. No forward travel or forced high knee is added.',
 'Comfortable steps; stand comfortably tall; opposite arm and leg; settle.',
 'Calling the in-place task exact traveling A-March, introducing flight, forcing thigh height, leaning back or adding repetitions while other groups work.',
 'The target follows the standardized base and isolates the rhythm/posture needed downstream. A separate traveling A-March or A-Skip would add route or impact demands beyond this short task.',
 'Method: counted stationary rhythm rehearsal. Tenets: Coordination/Body Control/Balance. Pattern: alternating no-flight support. Equipment: personal bay.',lambda a,m:march(),
 'Comfortable ordinary walking/support exchange and stop-cue participation must be present. Missing or unsuitable marching selects the explicit quiet-standing task, not forced supported marching. All three ages retain this small dose; experienced athletes receive a concise cue rather than added height/flight.',
 'Hold count, comfortable height and no-flight pattern. Record first fault; stop for symptoms or lost balance. A cleaner rhythm is useful without higher effort or an A-Skip upgrade.',
 'Actual instructional-base/OR-01 rhythm or equivalent →one counted basic rehearsal →selected corridor lesson →OR-08/12 retain actual preparation level and cue needs.'),
exercise('P2','Rehearse the start and ordinary runout on a short route','Prepare & Access','ACC-STATIC low-intent contextual use, or WALK-CORRIDOR-TEACH; no-travel adaptations separately declared',
 'One short counted rehearsal makes the release, finish marker and gradual runout concrete before the full corridor walk. It is preparation, not an unrecorded full-route test or a maximal acceleration set.',
 'The qualified low-intent route starts still in a comfortable bilateral standing stance, uses a smooth5m start, then slows gradually through10m protected runout and exits into its dedicated return. Unknown running readiness uses an ordinary15m corridor walk. Each route has its own active/return envelope below; no athlete walks the full35m route here. The main E0 task owns that longer physical orientation.',
 'Wait for release; smooth start; pass the finish; use the runout; walk back outside.',
 'Max effort from the first step, changing to a moving or three-point entry, stopping sharply at5m, entering the forward lane on return or adding a second rehearsal after a fault.',
 'The short route rehearses the entry/finish behavior within the fixed preparation budget. Its identity is acceleration teaching or walking, even when the later objective uses a longer upright running corridor.',
 'Method: single observed route rehearsal. Tenets: Coordination/Explosiveness/Body Control as eligible. Bodyweight; marked15m protected route and separate return.',lambda a,m:travel(a,m,'P2','short_walk' if m.endswith('_L') else 'short_acc'),
 'Running requires actual pain-free initiation, coordinated easy contacts and safe gradual runout plus understood release/return rules. OR-01 attendance alone is not evidence. Missing running evidence stays walking; no walking result passes acceleration. Symptoms or unsafe space defer travel or select a separately eligible stationary task.',
 'Retain standing start and easy intent. Count the first scheduled attempt, including faults, then wait for E0; no additional practice while queues form.',
 'Actual OR-01 route/start observation or direct equivalent →one short rehearsal →E0 counted full or short corridor walk →E1 only with its own running/space readiness.'),
exercise('E0','Walk the complete selected corridor','Explosiveness / instruction','WALK-CORRIDOR-TEACH — ordinary route orientation, not a braking or speed test',
 'This one physical walk teaches where the build, running finish, gradual runoff and outside return belong. It is counted in the lesson and workload before the athlete is asked to run that route.',
 'On the long route, walk0–10m build area,10–20m intended upright area and20–35m protected runoff, identify their markers in the coach’s allotted pause, then exit and walk back by the dedicated one-way return. On a short route, walk0–5m target and5–15m runout. Do not add a two-second athletic stick, turn-and-go or measured braking task. No-travel selection uses a quiet standing orientation while the coach explains the diagram; actual corridor travel remains unobserved.',
 'Name the finish; show the runoff; find the outside return; wait for the next release.',
 'Treating verbal knowledge as completed running, stopping at the running finish instead of using the remaining corridor, taking the forward lane back or leaving this walk out of total workload.',
 'The main block has time for an actual whole-route walk; the short preparation budget does not. Walking before running teaches corridor recognition while output stays low.',
 'Method: counted route walkthrough, full recovery. Tenets: Coordination/Body Control. Walking distance is separate from later running targets.',lambda a,m:travel(a,m,'E0','long_walk'),
 'Comfortable independent walking, simple release/stop communication and safe corridor/return are required. The first listed walk is the route observation, not an assumed completed prerequisite. If traffic understanding is incomplete, continue only an eligible walking or stationary teaching route. A long corridor that does not fit is a facility limitation, not an athlete failure.',
 'One walk only; no added walk to obtain a pass. Record actual route/marker/return mistakes. A corrected explanation does not retroactively turn an incomplete physical observation into a completed one.',
 'OR-01 conduct or equivalent and P2 short observation →one counted selected-corridor walk →separately eligible E1 →OR-08/12 retain the actual route and address only the remaining gap.'),
exercise('E1','Build smoothly into an easy upright rhythm','Explosiveness','EASY-BUILD-RUN-TEACH; independently eligible short acceleration/walking/stationary alternatives',
 'Each recovered easy-run set observes smooth buildup, comfortable upright rhythm and deliberate use of the finish/runoff. Standard D has two such attempts; compressed D has one. Standard L has one additional walking route observation; compressed L omits E1 after its counted E0 walk. No set seeks greater speed, longer distance or fatigue.',
 'Long D uses a still comfortable standing start, builds smoothly over0–10m from about2/10 toward3/10 effort, retains that relaxed effort through10–20m, then slows gradually through20–35m and exits before its outside return. This easy lesson has no maximal second half or timed fly. Limited space uses the separately labeled5m low-intent standing start plus10m runout. Walking and stationary routes retain their distinct prescriptions and results.',
 'Smooth build; comfortable tall rhythm; finish through the mark; slow gradually; return outside.',
 'Forcing upright posture immediately, sprinting all-out, reaching for stride length, treating the finish as a braking target, competing with another lane or recording a short start as upright-speed coverage.',
 'Recovered running follows the actual corridor walk, with familiar strength afterward. The legacy stride-out’s maximal prescription is not imported into this low-intent lesson. Extra mechanics drills and a running finisher are omitted to preserve observation and recovery.',
 'Method: recovered low-intent route/rhythm practice. Tenets: Speed/Explosiveness/Coordination/Body Control as actually practiced. Not maximal-velocity training.',lambda a,m:travel(a,m,'E1','long_walk' if m.endswith('_L') else 'long_run'),
 'Long running requires independently comfortable easy jogging, coordinated contacts/controlled gradual slowing, observed route conduct and a verified full corridor/return. The lesson does not require A-Skip merely because the related maximal legacy source lists it; neither does it qualify that legacy output profile. Age and a successful short start do not establish long-corridor readiness. Unknown readiness selects its own walking/stationary instruction; actual fatigue after OR-03 favors L where appropriate.',
 'Retain the chosen route, easy ceiling and familiar strength. Faults consume their opportunity and remain in workload; stop for symptoms or unsafe mechanics. OR-08 may consider only a justified gradual intent change after this route is repeatable; OR-12 later changes recognition of rest/return, not automatically speed or volume.',
 'Actual OR-01 participation/short-start evidence plus E0 route observation and independent easy-jog ability →today’s actual easy run or named substitute →OR-08 same route with a separately justified intent decision →OR-12 retained route/output with supervised recovery responsibility.')]

# Retain the exact familiar mechanics and export them fully. OR-04's supporting
# role, set purpose and progression replace every prior-session rationale/link.
old2=json.loads((ROOT/'instructional_on_ramp/week_01/or_02.json').read_text())
old3=json.loads((ROOT/'instructional_on_ramp/week_01/or_03.json').read_text())
prior2={e['key']:e for e in old2['exercises']};prior3={e['key']:e for e in old3['exercises']}
for key,source,mapping,name,role in [
 ('S1',prior2['S2'],'SQUAT-BW','Retain comfortable bilateral knee control','knee'),
 ('S2',prior3['S2'],'HINGE-BW','Retain the familiar hip hinge','hip'),
 ('S3',prior3['S3'],'INCLINE-PUSH','Retain supported pressing','push'),
 ('S4',prior3['S4'],'SUPPORTED-ROW','Retain supported pulling on both sides','pull'),
 ('S5',prior3['S5'],'HEEL-TAP','Retain a supported trunk during small heel taps','brace')]:
    item=copy.deepcopy(source);item.update(key=key,name=name,component='Strength',mapping=mapping)
    item['set_purpose']=f'One small familiar {role} set retains balanced full-body practice while corridor/rhythm instruction receives attention. Actual one-set history stays one; compatible actual two-set history is deliberately reduced to one supporting set today. Neither available time nor day number adds volume.'
    item['rationale']=f'This {role} role receives the same six-minute standard or four-minute compressed teaching block as every other strength role. Demonstration, apparatus/side changes, observation and recovery fit within that block; equal attention does not mean equal per-side repetition counts. The exact familiar variation/range/load is retained without adding a new loading emphasis.'
    item['continuity']=f'Actual OR-01/02/03 or direct equivalent {role} dose and response →one explicit compatible supporting set today →OR-08/12 retain actual familiar strength while the named running/return variable changes. A lighter or omitted prior exposure is recorded, not overwritten with an assumed standard baseline.'
    item['progression']='Hold the actual eligible variation, range, cadence and load. Current cue dependence, symptoms or fatigue may require a recorded smaller range, lighter listed dose or deferral; no missed work is owed. Running success does not authorize a strength upgrade.'
    exercises.append(item)

